int main(int argc,char** argv){try{std::string adapter;if(argc==3&&std::string(argv[1])=="--adapter")adapter=argv[2];else if(argc!=1)throw std::runtime_error("Usage: native_field_coordinator_gpu_tests [--adapter substring]");Rig rig(adapter);require(rig.debug,"Hardware validation required");const auto root=std::string("build/field-coordinator-gpu/");coupled(rig,e::loadCooked(root+"joint.cooked.json"));filteredRetirement(rig,e::loadCooked(root+"particle.cooked.json"),e::loadCooked(root+"smoke.cooked.json"));contracts(rig);const auto errors=rig.debugErrors();require(errors==0,"Coordinator D3D12 debug errors");std::cout<<nlohmann::json{{"schema","nativegpu.field-coordinator-gpu-evidence/1"},{"ok",true},{"groups",3},{"checks",checks},{"comparisons",comparisons},{"cases",cases},{"adapter",rig.adapter},{"debugLayer",rig.debug},{"debugErrors",errors},{"runtimeReadback",false},{"scope","Production runtime field coordinator owns one typed world, joint same-tick publication, query retirement routing and fixed memory partitions. Renderer integration is separately verified; CPU authority and full A-G remain pending."}}.dump()<<'\n';}catch(const std::exception& e){std::cerr<<"Field coordinator failed after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
